+++ b/src/index.js
 // QueenOS worker-starter: a dependency-free router. No build step: every
 // src/**/*.js file is uploaded as an ES module, so imports must be relative.
 import { features } from "./features/index.js";

 const json = (body, status = 200) =>
   new Response(JSON.stringify(body, null, 2) + "\n", {
     status,
     headers: { "content-type": "application/json; charset=utf-8" },
   });

+const escapeHtml = (s) =>
+  String(s).replace(/[&<>"']/g, (c) =>
+    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
+  );
+
+const statusPage = (featureSlugs) => {
+  const rows = featureSlugs
+    .map(
+      (slug) => `
+      <li class="card">
+        <a href="/features/${encodeURIComponent(slug)}">${escapeHtml(slug)}</a>
+        <span class="hint">/features/${escapeHtml(slug)}</span>
+      </li>`,
+    )
+    .join("\n");
+
+  return `<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Status — worker-starter</title>
+  <style>
+    :root { color-scheme: light dark; }
+    body {
+      font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
+      margin: 0 auto; padding: 2rem 1rem 4rem; max-width: 42rem; line-height: 1.5;
+    }
+    h1 { margin: 0 0 .25rem; font-size: 1.75rem; }
+    .sub { color: #6b7280; margin: 0 0 1.5rem; }
+    .badge {
+      display: inline-flex; align-items: center; gap: .4rem;
+      background: #ecfdf5; color: #047857; border: 1px solid #a7f3d0;
+      border-radius: 999px; padding: .15rem .75rem; font-size: .8rem; font-weight: 600;
+    }
+    .badge::before { content: ""; width: .5rem; height: .5rem; border-radius: 50%; background: #10b981; }
+    ul { list-style: none; padding: 0; margin: 1.25rem 0 0; display: grid; gap: .6rem; }
+    .card {
+      border: 1px solid #e5e7eb; border-radius: .5rem; padding: .75rem 1rem;
+      display: flex; align-items: baseline; justify-content: space-between; gap: 1rem;
+    }
+    .card a { font-weight: 600; text-decoration: none; }
+    .card a:hover { text-decoration: underline; }
+    .hint { color: #6b7280; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: .8rem; }
+    footer { margin-top: 2rem; color: #9ca3af; font-size: .8rem; }
+    @media (prefers-color-scheme: dark) {
+      .card { border-color: #374151; }
+      .badge { background: #052e1a; border-color: #065f46; }
+      .sub, .hint, footer { color: #9ca3af; }
+    }
+  </style>
+</head>
+<body>
+  <h1>Status</h1>
+  <p class="sub">
+    <span class="badge">All systems operational</span>
+  </p>
+  <p>worker-starter is running. Registered features:</p>
+  <ul>${rows}
+  </ul>
+  <footer>Machine-readable check: <code>/health</code> (JSON) · Generated ${new Date().toISOString()}</footer>
+</body>
+</html>`;
+};
+
+const html = (body, status = 200) =>
+  new Response(body, {
+    status,
+    headers: { "content-type": "text/html; charset=utf-8" },
+  });
+
 export default {
   async fetch(request) {
     const url = new URL(request.url);
     try {
       // Feature guards run on every request (auth, flags, rate limits, ...).
       for (const feature of features) {
         if (typeof feature.guard === "function") await feature.guard(request);
       }

       if (url.pathname === "/" || url.pathname === "") {
+        return html(statusPage(features.map((f) => f.slug)));
-        return json({ ok: true, app: "worker-starter", features: features.map((f) => f.slug) });
       }
       if (url.pathname === "/health") return json({ ok: true });

       const match = /^\/features\/([a-z0-9-]+)\/?$/.exec(url.pathname);
       if (match) {
         const feature = features.find((f) => f.slug === match[1]);
         if (feature) return await feature.handle(request);
       }
       return json({ ok: false, error: "not found", path: url.pathname }, 404);
     } catch (err) {
       return json({ ok: false, error: String((err && err.message) || err) }, 500);
     }
   },
 };

